class Segmenttree:
	(st, n) = ([], 0)

	def __init__(self, n, l):
		self.st = [0] * (2 * n)
		self.n = n
		for i in range(n):
			self.st[i + n] = l[i]
		for i in range(n - 1, 0, -1):
			self.st[i] = self.st[i << 1] + self.st[i << 1 | 1]

	def update(self, p, val):
		self.st[p + self.n] = val
		p += self.n
		while p > 1:
			self.st[p >> 1] = self.st[p] + self.st[p ^ 1]
			p >>= 1

	def query(self, l, r):
		(l, r) = (l + self.n, r + self.n)
		res = 0
		while l < r:
			if l & 1:
				res += self.st[l]
				l += 1
			if r & 1:
				r -= 1
				res += self.st[r]
			l >>= 1
			r >>= 1
		return res

